/**
 * What an import actually did.
 *
 * Reported field by field rather than as a single count, because the useful
 * question afterwards is "why did it not pick up book X?" and the answer is
 * almost always one of: the book is not in the catalogue, the status was
 * already correct, or the row could not be acted on at all.
 */
export interface ImportResultOut {
  /**
   * Books added from the file
   * @minimum 0
   */
  created: number;
  /**
   * Rows the file itself marked as not wanted, such as a title deleted at the source
   * @minimum 0
   */
  excluded?: number;
  /**
   * Rows matched to a book already here
   * @minimum 0
   */
  matched: number;
  /**
   * Rows this import acted on
   * @minimum 0
   */
  rows_read: number;
  /**
   * Rows this import could not act on: no title, or an ISBN held by a book the caller cannot see
   * @minimum 0
   */
  skipped: number;
  /**
   * Statuses actually changed
   * @minimum 0
   */
  statuses_updated: number;
  /**
   * Tag names this run tried to put on a book and did not: the name was empty, the book was already full, the run had invented all the tags it may, or the name is not one this member may use. Not a count of what the source held: a reader caps how many tag names it takes from one record, and a record acted on in no other way is not reached at all, so both lose names upstream of this number
   * @minimum 0
   */
  tags_dropped?: number;
  unmatched_titles?: string[];
}
